import { useState } from 'react'

export function ${NAME}() {
  const [value, setValue] = useState<unknown>(null)
  return { value, setValue }
}

import { createContext, useContext, type ReactNode } from 'react'

type ${NAME}Value = {}

const ${NAME}Context = createContext<${NAME}Value | null>(null)

export function ${NAME}Provider({ children }: { children: ReactNode }) {
  const value: ${NAME}Value = {}
  return <${NAME}Context.Provider value={value}>{children}</${NAME}Context.Provider>
}

export function use${NAME}() {
  const context = useContext(${NAME}Context)
  if (!context) {
    throw new Error('use${NAME} must be used inside ${NAME}Provider')
  }
  return context
}
